/**
 * Plugin Name: Test 2 Elementor Widgets
 * Description: Custom Elementor widgets with dynamic asset injection based on the Test 2 design.
 * Version: 1.0.0
 * Author: Jules
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit; // Exit if accessed directly.
}

define( 'TEST2_PLUGIN_DIR', plugin_dir_path( __FILE__ ) );
define( 'TEST2_PLUGIN_URL', plugin_dir_url( __FILE__ ) );

/**
 * Activation Hook: Copy resources to WordPress root.
 */
function test2_plugin_activate() {
	$res_dir = TEST2_PLUGIN_DIR . 'res/';
	$root_dir = ABSPATH;

	if ( ! is_dir( $res_dir ) ) {
		return;
	}

	$blocked_files = array( 'wp-config.php', '.htaccess', 'index.php', 'wp-settings.php', 'wp-login.php', 'wp-mail.php', 'xmlrpc.php' );
	test2_plugin_recursive_copy( $res_dir, $root_dir, $blocked_files );
}
register_activation_hook( __FILE__, 'test2_plugin_activate' );

function test2_plugin_recursive_copy( $src, $dst, $blocked_files = array() ) {
	if ( ! is_dir( $src ) ) return;
	$dir = opendir( $src );
	if ( ! is_dir( $dst ) ) {
		mkdir( $dst, 0755, true );
	}
	while ( false !== ( $file = readdir( $dir ) ) ) {
		if ( ( $file != '.' ) && ( $file != '..' ) ) {
			if ( is_dir( $src . '/' . $file ) ) {
				test2_plugin_recursive_copy( $src . '/' . $file, $dst . '/' . $file, $blocked_files );
			} else {
				if ( ! in_array( $file, $blocked_files ) ) {
					copy( $src . '/' . $file, $dst . '/' . $file );
				}
			}
		}
	}
	closedir( $dir );
}

/**
 * Global variable to track widget usage.
 */
$test2_widgets_used = false;

function test2_mark_widget_used() {
	global $test2_widgets_used;
	$test2_widgets_used = true;
}

/**
 * Inject Head Assets.
 */
function test2_inject_head_assets() {
	global $test2_widgets_used;
	if ( ! $test2_widgets_used && ! (class_exists('\Elementor\Plugin') && \Elementor\Plugin::$instance->editor->is_edit_mode()) ) {
		return;
	}
