 */
function test2_register_widgets( $widgets_manager ) {
	require_once( TEST2_PLUGIN_DIR . 'inc/widgets/header-widget.php' );
	require_once( TEST2_PLUGIN_DIR . 'inc/widgets/hero-widget.php' );
	require_once( TEST2_PLUGIN_DIR . 'inc/widgets/manifesto-widget.php' );
	require_once( TEST2_PLUGIN_DIR . 'inc/widgets/investors-widget.php' );
	require_once( TEST2_PLUGIN_DIR . 'inc/widgets/team-widget.php' );
	require_once( TEST2_PLUGIN_DIR . 'inc/widgets/footer-widget.php' );
	require_once( TEST2_PLUGIN_DIR . 'inc/widgets/extras-widget.php' );

	$widgets_manager->register( new \Test2_Header_Widget() );
	$widgets_manager->register( new \Test2_Hero_Widget() );
	$widgets_manager->register( new \Test2_Manifesto_Widget() );
	$widgets_manager->register( new \Test2_Investors_Widget() );
	$widgets_manager->register( new \Test2_Team_Widget() );
	$widgets_manager->register( new \Test2_Footer_Widget() );
	$widgets_manager->register( new \Test2_Extras_Widget() );
}
add_action( 'elementor/widgets/register', 'test2_register_widgets' );

