function test2_add_elementor_widget_categories( $elements_manager ) {
	$elements_manager->add_category(
		'test2-category',
		[
			'title' => esc_html__( 'Test 2 Widgets', 'test2' ),
			'icon' => 'fa fa-plug',
		]
	);
}
add_action( 'elementor/elements/categories_registered', 'test2_add_elementor_widget_categories' );
